11	/**
12	 * Client verso l'API esterna di un hub (design doc Parte 1 di atmosphera-admin,
13	 * roadmap hub #24). Stateless, un solo token di servizio, paginazione
14	 * page/per_page.
15	 */
16	class HubClient
17	{
18	    /**
19	     * Itera le pagine di una risorsa, yieldando l'array `data` di ciascuna.
20	     *
21	     * @return Generator<int, array<int, array<string, mixed>>>
22	     */
23	    public function paginate(string $resource, ?Carbon $updatedSince = null): Generator
24	    {
25	        $page = 1;
26	        $lastPage = 1;
27	
28	        do {
29	            $response = $this->request()->get($resource, array_filter([
30	                'page' => $page,
31	                'per_page' => config('hub-sync.per_page'),
32	                'updated_since' => $updatedSince?->toIso8601String(),
33	            ]));
34	
35	            if ($response->failed()) {
36	                throw new HubApiException(
37	                    "Chiamata a [{$resource}] pagina {$page} fallita con status {$response->status()}: {$response->body()}",
38	                );
39	            }
40	
41	            /** @var array{data?: array<int, array<string, mixed>>, meta?: array{last_page?: int}} $body */
42	            $body = $response->json();
43	
44	            yield $body['data'] ?? [];
45	
46	            $lastPage = (int) ($body['meta']['last_page'] ?? 1);
47	            $page++;
48	        } while ($page <= $lastPage);
49	    }
50	
51	    private function request(): \Illuminate\Http\Client\PendingRequest
52	    {
53	        /** @var string $configuredBaseUrl */
54	        $configuredBaseUrl = config('hub-sync.base_url');
55	        /** @var string $token */
56	        $token = config('hub-sync.token');
57	
58	        return Http::baseUrl(rtrim($configuredBaseUrl, '/') . '/api/v1')->withToken($token);
59	    }
60	}
