7	use AtrioTeam\HubSync\Models\SyncRun;
8	use Illuminate\Support\Carbon;
9	use Throwable;
10	
11	/**
12	 * Meccanica comune a ogni Syncer: paginazione, conteggi, cattura degli
13	 * errori per singolo record (senza bloccare il run) e watermark
14	 * incrementale sull'ultimo run riuscito per la stessa risorsa. Le
15	 * sottoclassi sanno solo come si chiama la risorsa sull'hub e come si fa
16	 * l'upsert di un singolo item.
17	 */
18	abstract class AbstractSyncer implements Syncer
19	{
20	    public function __construct(protected readonly HubClient $client = new HubClient())
21	    {
22	    }
23	
24	    abstract protected function resource(): string;
25	
26	    /**
27	     * @param array<string, mixed> $item
28	     * @return bool true se il record locale non esisteva ancora (creato)
29	     */
30	    abstract protected function upsert(array $item): bool;
31	
32	    public function sync(SyncRun $run): void
33	    {
34	        $watermark = $this->watermark();
35	        $itemErrors = [];
36	
37	        foreach ($this->client->paginate($this->resource(), $watermark) as $page) {
38	            foreach ($page as $item) {
39	                try {
40	                    $created = $this->upsert($item);
41	
42	                    $run->increment($created ? 'created_count' : 'updated_count');
43	                } catch (Throwable $e) {
44	                    $run->increment('failed_count');
45	                    $itemErrors[] = [
46	                        'global_id' => $item['global_id'] ?? null,
47	                        'message' => $e->getMessage(),
48	                    ];
49	                }
50	            }
51	        }
52	
53	        if ($itemErrors !== []) {
54	            $run->update(['item_errors' => $itemErrors]);
55	        }
56	    }
57	
58	    private function watermark(): ?Carbon
59	    {
60	        $lastSuccess = SyncRun::query()
61	            ->where('resource', $this->resource())
62	            ->where('status', SyncStatus::Success)
63	            ->latest('started_at')
64	            ->first();
65	
66	        if ($lastSuccess === null) {
67	            return null;
68	        }
69	
70	        /** @var Carbon|null $startedAt */
71	        $startedAt = $lastSuccess->started_at;
72	
73	        return $startedAt;
74	    }
75	}
